import itertools, json, random

def binary_rules_job(seed):
    fields = [{'name': f'f{i}', 'type': 'flag', 'domain': [0, 1]} for i in range(4)]
    slots = 4
    preds = []
    for slot in range(slots):
        for i in range(4):
            for v in (0, 1):
                preds.append({'kind': 'cmp', 'left': {'ref': [slot, f'f{i}']},
                              'op': 'eq', 'right': {'const': v, 'type': 'flag'}})
    train = []
    for zeros in range(0, 4):
        for combo in itertools.combinations(range(16), zeros):
            w = [1] * 16
            for c in combo:
                w[c] = 0
            train.append([w[i * 4:(i + 1) * 4] for i in range(4)])
    while len(train) < 700:
        train.append(train[0])
    r = random.Random(seed)
    queries = [{'target': [r.randrange(4), f'f{r.randrange(4)}'],
                'prefix': r.choice(['', '0', '1', '01', '10']), 'fixed': []} for _ in range(128)]
    return {'fields': fields, 'slots': slots, 'predicates': preds, 'width': 4,
            'train': train, 'approved': [], 'queries': queries}

def ne_conflict_job():
    dom = list(range(32))
    preds = [{'kind': 'all', 'field': 'x', 'op': 'ne', 'value': v} for v in range(32)]
    rows = [list(t) for t in itertools.combinations(range(32), 3)]
    train = rows[:]
    while len(train) < 10000:
        train.append(rows[len(train) % len(rows)])
    return {'fields': [{'name': 'x', 'type': 'count', 'domain': dom}], 'slots': 3,
            'predicates': preds, 'width': 4, 'train': train, 'approved': [], 'queries': []}

def medium_job(seed, nfields, slots, ntrain, nqueries):
    fields = [{'name': f'g{i}', 'type': 'count', 'domain': list(range(8))} for i in range(nfields)]
    r = random.Random(seed)
    preds = []
    for slot in range(slots):
        for i in range(nfields):
            preds.append({'kind': 'cmp', 'left': {'ref': [slot, f'g{i}']}, 'op': 'le',
                          'right': {'const': c, 'type': 'count'}} for c in (0, 2, 4, 6))
    preds = preds[:32]
    train = [[[r.randrange(8) for _ in range(nfields)] for _ in range(slots)] for _ in range(ntrain)]
    queries = [{'target': [r.randrange(slots), f'g{r.randrange(nfields)}'],
                'prefix': r.choice(['', '1', '7', '3']), 'fixed': []} for _ in range(nqueries)]
    return {'fields': fields, 'slots': slots, 'predicates': preds, 'width': 4,
            'train': train, 'approved': [], 'queries': queries}

jobs = [binary_rules_job(1), ne_conflict_job()]
for s in range(4):
    jobs.append(medium_job(10 + s, 3, 4, 2000, 0))
print('universe sizes', [ (len(j['fields'][0]['domain']) ** (j['slots'] * len(j['fields']))) for j in jobs])
raw = json.dumps({'jobs': jobs})
open('/workspace/tmp/batch2.json', 'w').write(raw)
print('input bytes', len(raw))
